      stem = `${d} − ${b} × ${c}`;
      answer = d - b * c;
      ltr = (d - b) * c;
      steps = [`Multiply first: ${b} × ${c} = ${b * c}.`, `Then subtract: ${d} − ${b * c} = ${answer}.`];
