// ---------------------------------------------------------------- helpers

function divisorsOf(n: number): number[] {
  const out: number[] = [];
  for (let i = 1; i <= n; i++) if (n % i === 0) out.push(i);
  return out;
}

function smallestFactor(n: number): number {
  for (let i = 2; i * i <= n; i++) if (n % i === 0) return i;
  return n;
}

function nearestNonFactor(n: number, rng: RNG): number {
  for (let tries = 0; tries < 40; tries++) {
    const c = rng.int(2, Math.max(3, Math.floor(n / 2)));
    if (n % c !== 0) return c;
  }
  return 7;
}

function listMultiples(x: number, upTo: number): string {
  const out: number[] = [];
  for (let k = 1; x * k <= upTo && out.length < 14; k++) out.push(x * k);
  const shown = out.join(', ');
  return out[out.length - 1] === upTo ? shown : shown + ', …';
}

function writtenNum(label: string): number {
  return parseInt(label.split('/')[0], 10);
}
function writtenDen(label: string): number {
  return parseInt(label.split('/')[1] ?? '1', 10);
}

function percentageWorking(amount: Rational, pct: number, answer: Rational) {
  const ten = amount.div(new Rational(10));
  const five = ten.div(new Rational(2));
  const steps: { say: string }[] = [{ say: `10% of ${money(amount)} is ${money(ten)}.` }];
  if (pct % 10 === 0) {
    steps.push({ say: `${pct}% is ${pct / 10} lot${pct / 10 === 1 ? '' : 's'} of 10%.` });
  } else {
    steps.push({ say: `5% is half of that: ${money(five)}.` });
    const tens = Math.floor(pct / 10);
    steps.push({
      say: tens === 0
        ? `${pct}% is that 5%.`
        : `${pct}% is ${tens} lot${tens === 1 ? '' : 's'} of 10% plus one 5%.`,
    });
  }
  steps.push({ say: `= ${money(answer)}` });
  return steps;
}

function ordinalWord(i: number): string {
  return ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh'][i] ?? String(i + 1) + 'th';
}

function columnName(powerOfTen: number): string {
  return (
    ['units', 'tens', 'hundreds', 'thousands', 'ten thousands', 'hundred thousands', 'millions'][
      powerOfTen
    ] ?? `10^${powerOfTen}`
  );
}
